def _endpoint_candidates(
    listing: _ListingRef,
    category: DataCategory,
    *,
    company_metadata_business_intro_requested: bool = False,
    company_metadata_xq_basic_info_requested: bool = False,
    company_metadata_cninfo_profile_requested: bool = False,
    statement_date_requested: bool = False,
    corporate_action_date_requested: bool = False,
    corporate_action_ipo_summary_requested: bool = False,
    corporate_action_ipo_yield_requested: bool = False,
    share_capital_date_requested: bool = False,
    share_capital_restricted_release_requested: bool = False,
    share_capital_individual_info_requested: bool = False,
    goodwill_impairment_forecast_requested: bool = False,
    goodwill_impairment_market_profile_requested: bool = False,
    goodwill_impairment_detail_requested: bool = False,
    goodwill_impairment_industry_data_requested: bool = False,
    ownership_pledge_company_distribution_requested: bool = False,
    ownership_pledge_bank_distribution_requested: bool = False,
    ownership_pledge_industry_data_requested: bool = False,
    ownership_pledge_market_profile_requested: bool = False,
    ownership_pledge_market_detail_requested: bool = False,
    ownership_pledge_detail_requested: bool = False,
    ownership_pledge_equity_mortgage_requested: bool = False,
    dividend_snapshot_date_requested: bool = False,
    dividend_detail_requested: bool = False,
    disclosure_individual_requested: bool = False,
    disclosure_market_requested: bool = False,
    disclosure_shareholder_meeting_requested: bool = False,
    shareholder_count_date_requested: bool = False,
    shareholder_count_detail_requested: bool = False,
    shareholder_control_requested: bool = False,
    shareholder_free_top10_requested: bool = False,
    shareholder_free_holding_detail_requested: bool = False,
    shareholder_top10_requested: bool = False,
    shareholder_hsgt_individual_requested: bool = False,
    insider_cninfo_management_detail_requested: bool = False,
    insider_management_person_requested: bool = False,
    insider_executive_share_changes_requested: bool = False,
    insider_management_detail_requested: bool = False,
    market_activity_statistic_requested: bool = False,
    market_activity_institution_statistic_requested: bool = False,
    market_activity_legu_requested: bool = False,
    market_activity_congestion_requested: bool = False,
    market_activity_ebs_requested: bool = False,
    market_activity_buffett_requested: bool = False,
    market_activity_ttm_lyr_requested: bool = False,
    market_activity_all_pb_requested: bool = False,
    market_activity_market_pe_requested: bool = False,
    market_activity_index_pe_requested: bool = False,
    market_activity_market_pb_requested: bool = False,
    market_activity_account_statistics_requested: bool = False,
    market_activity_block_trade_requested: bool = False,
    market_activity_institution_daily_requested: bool = False,
    market_activity_institution_research_requested: bool = False,
    market_activity_institution_research_detail_requested: bool = False,
    market_activity_industry_board_requested: bool = False,
    market_activity_szse_area_summary_requested: bool = False,
    market_activity_szse_sector_summary_requested: bool = False,
    market_activity_szse_summary_requested: bool = False,
    market_activity_sse_deal_daily_requested: bool = False,
    market_activity_sse_summary_requested: bool = False,
    market_activity_hot_rank_latest_requested: bool = False,
    market_activity_hk_hot_rank_detail_requested: bool = False,
    market_activity_hot_rank_detail_requested: bool = False,
    market_activity_participation_desire_requested: bool = False,
    market_activity_focus_requested: bool = False,
    market_activity_institution_participation_requested: bool = False,
    market_activity_limit_up_pool_requested: bool = False,
    market_activity_limit_down_pool_requested: bool = False,
    market_activity_hot_rank_requested: bool = False,
    market_activity_new_stock_requested: bool = False,
    market_quote_hk_main_board_requested: bool = False,
    market_quote_ah_comparison_requested: bool = False,
    market_quote_ab_comparison_requested: bool = False,
    market_quote_xq_requested: bool = False,
    market_quote_bid_ask_requested: bool = False,
    market_history_intraday_requested: bool = False,
    market_history_hk_intraday_requested: bool = False,
    market_history_pre_market_requested: bool = False,
    market_history_sina_minute_requested: bool = False,
    market_history_tencent_daily_requested: bool = False,
    market_history_tencent_tick_requested: bool = False,
    market_history_chip_distribution_requested: bool = False,
    market_history_intraday_trades_requested: bool = False,
    market_history_sina_intraday_requested: bool = False,
) -> tuple[str, ...]:
    market = listing.market
    if category is DataCategory.COMPANY_METADATA:
        if company_metadata_business_intro_requested:
            if market is ListingMarket.A:
                return ("stock_zyjs_ths",)
            return ()
        if company_metadata_xq_basic_info_requested:
            if market is ListingMarket.A:
                return ("stock_individual_basic_info_xq",)
            return ()
        if company_metadata_cninfo_profile_requested:
            if market is ListingMarket.A:
                return ("stock_profile_cninfo",)
            return ()
        if market is ListingMarket.A:
            return ("stock_info_a_code_name", "stock_zh_ah_name")
        return ("stock_hk_company_profile_em", "stock_zh_ah_name", "stock_hk_spot_em")
    if category is DataCategory.LISTING_METADATA:
        if market is ListingMarket.A:
            return ("stock_info_a_code_name", "stock_zh_ah_name")
        return ("stock_hk_security_profile_em", "stock_zh_ah_name", "stock_hk_spot_em")
    if category is DataCategory.RISK_WARNING_STATUS:
        if market is ListingMarket.A:
            return ("stock_zh_a_st_em",)
        return ()
    if category is DataCategory.ESG_RATINGS:
        return ("stock_esg_rate_sina",)
    if category is DataCategory.MARGIN_TRADING:
        if market is ListingMarket.A and listing.canonical_id.startswith("SH"):
            return ("stock_margin_detail_sse",)
