def _market_quote_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    if endpoint_name == "stock_zh_ab_comparison_em":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare A+B comparison endpoint supports A-share listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(
            set(request.parameters) - _MARKET_QUOTE_AB_COMPARISON_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare A+B comparison parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _MARKET_QUOTE_AB_COMPARISON_VIEW:
            raise ProviderRequestError(
                "the AKShare A+B comparison endpoint requires "
                f"view={_MARKET_QUOTE_AB_COMPARISON_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {}
    if endpoint_name == "stock_individual_spot_xq":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare Xueqiu individual-spot endpoint supports A-share listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(set(request.parameters) - _MARKET_QUOTE_XQ_PARAMETER_NAMES)
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare Xueqiu individual-spot parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _MARKET_QUOTE_XQ_VIEW:
            raise ProviderRequestError(
                "the AKShare Xueqiu individual-spot endpoint requires "
                f"view={_MARKET_QUOTE_XQ_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {"symbol": listing.canonical_id}
    if endpoint_name == "stock_zh_ah_spot_em":
        unknown = sorted(
            set(request.parameters) - _MARKET_QUOTE_AH_COMPARISON_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare A+H comparison parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _MARKET_QUOTE_AH_COMPARISON_VIEW:
            raise ProviderRequestError(
                "the AKShare A+H comparison endpoint requires "
                f"view={_MARKET_QUOTE_AH_COMPARISON_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {}
    if endpoint_name == "stock_hk_main_board_spot_em":
        if listing.market is not ListingMarket.H:
            raise ProviderRequestError(
                "the AKShare H-share main-board quote endpoint supports H-share "
                "listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(
            set(request.parameters) - _MARKET_QUOTE_HK_MAIN_BOARD_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare H-share main-board quote parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _MARKET_QUOTE_HK_MAIN_BOARD_VIEW:
            raise ProviderRequestError(
                "the AKShare H-share main-board quote endpoint requires "
                f"view={_MARKET_QUOTE_HK_MAIN_BOARD_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {}
    if endpoint_name != "stock_bid_ask_em":
        if endpoint_name in {"stock_zh_a_spot_em", "stock_zh_a_spot"}:
            _reject_unexpected_parameters(request)
            return {}
        if endpoint_name in {"stock_hk_spot_em", "stock_hk_spot"}:
            _reject_unexpected_parameters(request)
            return {}
        raise ProviderRequestError(
            f"unsupported AKShare market-quote endpoint {endpoint_name!r}",
            request=request,
            retryable=False,
        )
    if listing.market is not ListingMarket.A or listing.canonical_id[:2] not in {"SH", "SZ"}:
        raise ProviderRequestError(
            "the AKShare bid-ask endpoint supports Shanghai and Shenzhen A-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(set(request.parameters) - _MARKET_QUOTE_BID_ASK_PARAMETER_NAMES)
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare bid-ask parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    if request.parameters.get("view") != _MARKET_QUOTE_BID_ASK_VIEW:
        raise ProviderRequestError(
            "the AKShare bid-ask endpoint requires "
            f"view={_MARKET_QUOTE_BID_ASK_VIEW!r}",
            request=request,
            retryable=False,
        )
    return {"symbol": listing.code}


def _company_metadata_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    """Build the documented company-metadata request for each endpoint."""

    if endpoint_name == "stock_zyjs_ths":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare Tonghuashun main-business-introduction endpoint supports "
                "A-share listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(
            set(request.parameters) - _COMPANY_METADATA_BUSINESS_INTRO_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare Tonghuashun main-business-introduction "
                "parameter(s): " + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _COMPANY_METADATA_BUSINESS_INTRO_VIEW:
            raise ProviderRequestError(
                "the AKShare Tonghuashun main-business-introduction endpoint requires "
                f"view={_COMPANY_METADATA_BUSINESS_INTRO_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {"symbol": listing.code}

    if endpoint_name == "stock_individual_basic_info_xq":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare Xueqiu individual-basic-info endpoint supports A-share "
                "listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(
            set(request.parameters) - _COMPANY_METADATA_XQ_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare Xueqiu individual-basic-info parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _COMPANY_METADATA_XQ_VIEW:
            raise ProviderRequestError(
                "the AKShare Xueqiu individual-basic-info endpoint requires "
                f"view={_COMPANY_METADATA_XQ_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {"symbol": listing.canonical_id}

    if endpoint_name == "stock_profile_cninfo":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare CNINFO company-profile endpoint supports A-share "
                "listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(
            set(request.parameters) - _COMPANY_METADATA_CNINFO_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare CNINFO company-profile parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _COMPANY_METADATA_CNINFO_PROFILE_VIEW:
            raise ProviderRequestError(
                "the AKShare CNINFO company-profile endpoint requires "
                f"view={_COMPANY_METADATA_CNINFO_PROFILE_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {"symbol": listing.code}

    if endpoint_name in _NO_ARGUMENT_ENDPOINTS:
        _reject_unexpected_parameters(request)
        return {}
    _reject_unexpected_parameters(request)
    return {"symbol": listing.code}


