def _disclosure_notices_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    if endpoint_name == "stock_gddh_em":
        return _shareholder_meeting_kwargs(listing, request)
    if endpoint_name == "stock_notice_report":
        return _market_disclosure_notice_kwargs(listing, request)
    if endpoint_name == "stock_individual_notice_report":
        return _individual_disclosure_notice_kwargs(listing, request)
    if endpoint_name != "stock_zh_a_disclosure_report_cninfo":
        raise ProviderRequestError(
            f"unsupported AKShare disclosure-notice endpoint {endpoint_name!r}",
            request=request,
            retryable=False,
        )
    if listing.market is not ListingMarket.A:
        raise ProviderRequestError(
            "the AKShare disclosure-notice endpoint supports A-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(set(request.parameters) - _DISCLOSURE_NOTICES_PARAMETER_NAMES)
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare disclosure-notice parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )

    market = request.parameters.get("market", _DISCLOSURE_NOTICES_DEFAULT_MARKET)
    if market != _DISCLOSURE_NOTICES_MARKET:
        raise ProviderRequestError(
            "AKShare disclosure-notice market must be '沪深京' for A-share listings",
            request=request,
            retryable=False,
        )
    keyword = request.parameters.get("keyword", _DISCLOSURE_NOTICES_DEFAULT_KEYWORD)
    if not isinstance(keyword, str):
        raise ProviderRequestError(
            "AKShare disclosure-notice keyword must be a string",
            request=request,
            retryable=False,
        )
    category = request.parameters.get("category", _DISCLOSURE_NOTICES_DEFAULT_CATEGORY)
    if not isinstance(category, str) or category not in _DISCLOSURE_NOTICE_CATEGORIES:
        choices = ", ".join(sorted(value for value in _DISCLOSURE_NOTICE_CATEGORIES if value))
        raise ProviderRequestError(
            "AKShare disclosure-notice category must be empty or one of: " + choices,
            request=request,
            retryable=False,
        )
    start_date, start_value = _disclosure_notices_date_parameter(
        request.parameters.get("start_date", _DISCLOSURE_NOTICES_DEFAULT_START_DATE),
        name="start_date",
        request=request,
    )
    end_date, end_value = _disclosure_notices_date_parameter(
        request.parameters.get("end_date", _DISCLOSURE_NOTICES_DEFAULT_END_DATE),
        name="end_date",
        request=request,
    )
    if start_value > end_value:
        raise ProviderRequestError(
            "disclosure-notice start_date must not be after end_date",
            request=request,
            retryable=False,
        )
    return {
        "symbol": listing.code,
        "market": market,
        "keyword": keyword,
        "category": category,
        "start_date": start_date,
        "end_date": end_date,
    }


def _individual_disclosure_notice_kwargs(
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    """Build the documented Eastmoney individual-notice request."""

    if listing.market is not ListingMarket.A:
        raise ProviderRequestError(
            "the AKShare individual-notice endpoint supports A-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(
        set(request.parameters) - _DISCLOSURE_INDIVIDUAL_PARAMETER_NAMES
    )
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare individual-notice parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    if request.parameters.get("view") != _DISCLOSURE_INDIVIDUAL_VIEW:
        raise ProviderRequestError(
            "AKShare individual-notice view must be 'individual_notice'",
            request=request,
            retryable=False,
        )

    category = request.parameters.get(
        "category",
        _DISCLOSURE_INDIVIDUAL_DEFAULT_CATEGORY,
    )
    if not isinstance(category, str) or category not in _DISCLOSURE_INDIVIDUAL_CATEGORIES:
        choices = ", ".join(sorted(_DISCLOSURE_INDIVIDUAL_CATEGORIES))
        raise ProviderRequestError(
            "AKShare individual-notice category must be one of: " + choices,
            request=request,
            retryable=False,
        )
    start_date, start_value = _individual_disclosure_notice_date_parameter(
        request.parameters.get("start_date"),
        name="start_date",
        request=request,
    )
    end_date, end_value = _individual_disclosure_notice_date_parameter(
        request.parameters.get("end_date"),
        name="end_date",
        request=request,
    )
    if (
        start_value is not None
        and end_value is not None
        and start_value > end_value
    ):
        raise ProviderRequestError(
            "individual-notice start_date must not be after end_date",
            request=request,
            retryable=False,
        )
    return {
        "security": listing.code,
        "symbol": category,
        "begin_date": start_date,
        "end_date": end_date,
    }


