def _financial_statement_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
    *,
    statement_symbol: str,
    statement_label: str,
) -> dict[str, object]:
    unknown = sorted(set(request.parameters) - _FINANCIAL_STATEMENT_PARAMETER_NAMES)
    if unknown:
        raise ProviderRequestError(
            f"unsupported AKShare {statement_label} parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    if endpoint_name in _OFFICIAL_BALANCE_SHEET_ENDPOINTS:
        if "indicator" in request.parameters:
            raise ProviderRequestError(
                f"the A-share aggregate {statement_label} endpoint does not accept indicator",
                request=request,
                retryable=False,
            )
        if "statement_date" not in request.parameters:
            raise ProviderRequestError(
                f"the A-share aggregate {statement_label} endpoint requires "
                "statement_date (YYYY-MM-DD or YYYYMMDD)",
                request=request,
                retryable=False,
            )
        statement_date = _parse_statement_date_parameter(
            request.parameters["statement_date"],
            request=request,
        )
        return {"date": statement_date.strftime("%Y%m%d")}
    indicator = str(request.parameters.get("indicator", "annual")).lower()
    indicators = {
        "annual": "年度",
        "yearly": "年度",
        "reporting": "报告期",
        "report": "报告期",
        "年度": "年度",
        "报告期": "报告期",
    }
    if indicator not in indicators:
        raise ProviderRequestError(
            f"{statement_label} indicator must be annual or reporting",
            request=request,
            retryable=False,
        )
    if endpoint_name == "stock_cash_flow_sheet_by_report_em":
        if "statement_date" in request.parameters:
            raise ProviderRequestError(
                f"the A-share report-period {statement_label} endpoint does not "
                "accept statement_date",
                request=request,
                retryable=False,
            )
        if "indicator" in request.parameters:
            raise ProviderRequestError(
                f"the A-share report-period {statement_label} endpoint does not accept indicator",
                request=request,
                retryable=False,
            )
        return {"symbol": listing.canonical_id}
    if endpoint_name == "stock_profit_sheet_by_report_em":
        if "statement_date" in request.parameters:
            raise ProviderRequestError(
                f"the A-share report-period {statement_label} endpoint does not "
                "accept statement_date",
                request=request,
                retryable=False,
            )
        if "indicator" in request.parameters:
            raise ProviderRequestError(
                f"the A-share report-period {statement_label} endpoint does not accept indicator",
                request=request,
                retryable=False,
            )
        return {"symbol": listing.canonical_id}
    if endpoint_name == "stock_balance_sheet_by_report_em":
        if "statement_date" in request.parameters:
            raise ProviderRequestError(
                f"the A-share report-period {statement_label} endpoint does not "
                "accept statement_date",
                request=request,
                retryable=False,
            )
        if "indicator" in request.parameters:
            raise ProviderRequestError(
                f"the A-share report-period {statement_label} endpoint does not accept indicator",
                request=request,
                retryable=False,
            )
        return {"symbol": listing.canonical_id}
    if endpoint_name == "stock_financial_report_sina":
        if "statement_date" in request.parameters:
            raise ProviderRequestError(
                f"the Sina {statement_label} endpoint does not accept statement_date",
                request=request,
                retryable=False,
            )
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the Sina financial-report endpoint supports A-share listings only",
                request=request,
                retryable=False,
            )
        return {"stock": listing.canonical_id.lower(), "symbol": statement_symbol}
    if endpoint_name == "stock_financial_hk_report_em":
        if "statement_date" in request.parameters:
            raise ProviderRequestError(
                f"the H-share {statement_label} endpoint does not accept statement_date",
                request=request,
                retryable=False,
            )
        return {
            "stock": listing.code,
            "symbol": statement_symbol,
            "indicator": indicators[indicator],
        }
    raise ProviderRequestError(
        f"unsupported AKShare {statement_label} endpoint {endpoint_name!r}",
        request=request,
        retryable=False,
    )


def _parse_listing_id(
    entity_id: str,
    *,
    provider: ProviderIdentity | None = None,
    request: ProviderRequest | None = None,
) -> _ListingRef:
    if not isinstance(entity_id, str) or not entity_id.strip():
        raise ProviderRequestError(
            "entity_id must identify an A or H listing",
            provider=provider,
            request=request,
            retryable=False,
        )
    value = re.sub(r"\s+", "", entity_id).upper()

    match = re.fullmatch(r"(SH|SZ|BJ)(\d{6})", value)
    if match:
        exchange, code = match.groups()
        return _ListingRef(ListingMarket.A, code, exchange + code)
    match = re.fullmatch(r"HK(\d{1,5})", value)
    if match:
        code = match.group(1).zfill(5)
        return _ListingRef(ListingMarket.H, code, "HK" + code)
    match = re.fullmatch(r"A[:.]?(\d{6})", value)
    if match:
        code = match.group(1)
        return _ListingRef(ListingMarket.A, code, _inferred_a_prefix(code) + code)
    match = re.fullmatch(r"H[:.]?(\d{1,5})", value)
    if match:
        code = match.group(1).zfill(5)
        return _ListingRef(ListingMarket.H, code, "HK" + code)
    match = re.fullmatch(r"(\d{6})\.(SH|SS|SZ|BJ)", value)
    if match:
        code, exchange = match.groups()
        exchange = "SH" if exchange == "SS" else exchange
        return _ListingRef(ListingMarket.A, code, exchange + code)
    match = re.fullmatch(r"(\d{1,5})\.HK", value)
    if match:
        code = match.group(1).zfill(5)
        return _ListingRef(ListingMarket.H, code, "HK" + code)
    if re.fullmatch(r"\d{6}", value):
        return _ListingRef(ListingMarket.A, value, _inferred_a_prefix(value) + value)
    if re.fullmatch(r"\d{1,5}", value):
        code = value.zfill(5)
        return _ListingRef(ListingMarket.H, code, "HK" + code)

    raise ProviderRequestError(
        f"unsupported A/H listing identifier: {entity_id!r}",
        provider=provider,
        request=request,
        retryable=False,
    )


def _inferred_a_prefix(code: str) -> str:
    if code.startswith("6"):
        return "SH"
    if code.startswith(("4", "8")):
        return "BJ"
    return "SZ"


def _same_listing(canonical_id: str, other: str) -> bool:
    try:
        return canonical_id == _parse_listing_id(other).canonical_id
    except ProviderError:
        return canonical_id == str(other).strip().upper()


def _canonical_row_code(value: object, market: ListingMarket) -> str | None:
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, Real):
        numeric = float(value)
        if not math.isfinite(numeric):
            return None
        text = str(int(numeric)) if numeric.is_integer() else str(numeric)
    else:
        text = str(value).strip().upper()
    if text.lower() in _MISSING_TEXT:
        return None
    digits = re.findall(r"\d+", text)
    if not digits:
        return None
    code = "".join(digits)
    if market is ListingMarket.A:
        if len(code) > 6:
            code = code[-6:]
        return code.zfill(6)
    if len(code) > 5:
        code = code[-5:]
    return code.zfill(5)


def _row_code(row: Mapping[str, JSONValue], market: ListingMarket) -> str | None:
    if market is ListingMarket.A:
        keys = (
            "A股代码",
            "股票代码",
            "证券代码",
            "公司代码",
            "SECURITY_CODE",
            "SECUCODE",
            "code",
            "symbol",
            "代码",
        )
    else:
        keys = (
            "H股代码",
            "SECURITY_CODE",
            "SECUCODE",
            "证券代码",
            "公司代码",
            "股票代码",
            "code",
            "symbol",
            "代码",
        )
    for key in keys:
        if key in row:
            code = _canonical_row_code(row[key], market)
            if code is not None:
                return code
    return None


def _margin_trading_row_code(row: Mapping[str, JSONValue]) -> str | None:
    """Read the documented SSE/SZSE/BSE margin-detail security code."""

    for key in _MARGIN_TRADING_CODE_FIELDS:
        if key in row:
            code = _canonical_row_code(row[key], ListingMarket.A)
            if code is not None:
                return code
    return None


def _esg_rating_row_listing(row: Mapping[str, JSONValue]) -> _ListingRef | None:
    """Parse one documented ESG row's explicit code and ``cn``/``hk`` market."""

    found_code, raw_code = _lookup(row, _ESG_RATING_CODE_FIELDS)
    code_text = _text_value(raw_code) if found_code else None
    if code_text is None:
        return None

    found_market, raw_market = _lookup(row, _ESG_RATING_MARKET_FIELDS)
    market_text = _text_value(raw_market) if found_market else None
    if market_text is None:
        raise ValueError("ESG-rating row has no explicit market")
    market_values = {"cn": ListingMarket.A, "hk": ListingMarket.H}
    market = market_values.get(market_text.casefold())
    if market is None:
        raise ValueError(
            f"ESG-rating row market {market_text!r} must be 'cn' or 'hk'"
        )

    if market is ListingMarket.A and re.fullmatch(r"\d{6}", code_text):
        return _ListingRef(
            ListingMarket.A,
            code_text,
            _inferred_a_prefix(code_text) + code_text,
        )
    if market is ListingMarket.H and re.fullmatch(r"\d{1,5}", code_text):
        code = code_text.zfill(5)
        return _ListingRef(ListingMarket.H, code, "HK" + code)

    try:
        parsed = _parse_listing_id(code_text)
    except ProviderError as exc:
        raise ValueError(f"ESG-rating row listing code {code_text!r} is invalid") from exc
    if parsed.market is not market:
        raise ValueError(
            f"ESG-rating row listing code {code_text!r} conflicts with market {market_text!r}"
        )
    return parsed


def _to_json_value(value: object, *, path: str = "response") -> JSONValue:
    """Convert pandas/numpy-like results to strict JSON without zero-filling."""

    if value is None:
        return None
    if type(value).__name__ in {"NAType", "NaTType"}:
        return None
    if isinstance(value, (str, bool)):
        return value
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, date):
        return value.isoformat()
    if isinstance(value, Integral) and not isinstance(value, bool):
        return int(value)
    if isinstance(value, Real) and not isinstance(value, bool):
        numeric = float(value)
        if math.isnan(numeric):
            return None
        if not math.isfinite(numeric):
            raise ProviderResponseError(f"{path} contains infinity")
        return numeric
    if isinstance(value, Mapping):
        converted: dict[str, JSONValue] = {}
        for key, child in value.items():
            if not isinstance(key, str):
                raise ProviderResponseError(f"{path} has a non-string object key")
            converted[key] = _to_json_value(child, path=f"{path}.{key}")
        return converted
    if isinstance(value, (list, tuple)):
        return [_to_json_value(child, path=f"{path}[{index}]") for index, child in enumerate(value)]

    to_dict = getattr(value, "to_dict", None)
    if callable(to_dict):
        try:
            tabular = to_dict(orient="records")
        except TypeError:
            try:
                tabular = to_dict("records")
            except Exception as exc:
                raise ProviderResponseError(f"{path} could not be converted to records") from exc
        return _to_json_value(tabular, path=path)

    item = getattr(value, "item", None)
    if callable(item):
        try:
            return _to_json_value(item(), path=path)
        except Exception as exc:
            if isinstance(exc, ProviderResponseError):
                raise
            raise ProviderResponseError(f"{path} contains an unsupported scalar") from exc
    raise ProviderResponseError(f"{path} has unsupported type {type(value).__name__}")


def _table_rows(
    payload: JSONValue,
    *,
    provider: ProviderIdentity | None = None,
    request: ProviderRequest | None = None,
) -> list[dict[str, JSONValue]]:
    if payload is None:
        return []
    if isinstance(payload, Mapping):
        data = payload.get("data")
        if isinstance(data, list):
            payload = data
        else:
            return [dict(payload)]
    if not isinstance(payload, list):
        raise ProviderResponseError(
            "tabular AKShare response must be an object, array or null",
            provider=provider,
            request=request,
        )
    rows: list[dict[str, JSONValue]] = []
    for index, item in enumerate(payload):
        if not isinstance(item, Mapping):
            raise ProviderResponseError(
                f"AKShare tabular response row {index} is not an object",
                provider=provider,
                request=request,
            )
        rows.append(dict(item))
    return rows


def _select_listing_row(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> dict[str, JSONValue]:
    matches = [row for row in rows if _row_code(row, listing.market) == listing.code]
    if len(matches) == 1:
        return dict(matches[0])
    if len(matches) > 1:
        raise ProviderResponseError(
            f"AKShare returned ambiguous rows for {request.entity_id!r}",
            provider=provider,
            request=request,
        )
    if len(rows) == 1 and _row_code(rows[0], listing.market) is None:
        return dict(rows[0])
    raise ProviderResponseError(
        f"AKShare returned no row for {request.entity_id!r}",
        provider=provider,
        request=request,
    )


def _select_listing_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
    row_label: str = "corporate-action",
) -> list[dict[str, JSONValue]]:
    """Filter a universe response without discarding matching history rows."""

    if any(_row_code(row, listing.market) is None for row in rows):
        raise ProviderResponseError(
            f"AKShare returned a {row_label} row without a listing code for "
            f"{request.entity_id!r}",
            provider=provider,
            request=request,
        )
    return [dict(row) for row in rows if _row_code(row, listing.market) == listing.code]


def _validate_corporate_action_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> None:
    """Reject explicitly cross-listed rows before storing raw evidence."""

    for row in rows:
        row_code = _row_code(row, listing.market)
        if row_code is not None and row_code != listing.code:
            raise ProviderResponseError(
                f"AKShare returned corporate-action row entity {row_code!r} for "
                f"requested listing {listing.canonical_id!r}",
                provider=provider,
                request=request,
            )


def _ipo_summary_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
) -> str | None:
    """Return a strict-schema error for one documented IPO-summary row."""

    if len(rows) != 1:
        return f"A-share IPO-summary response must contain exactly one row; got {len(rows)}"

    row = rows[0]
    missing = sorted(_IPO_SUMMARY_FIELDS - set(row))
    if missing:
        return "A-share IPO-summary row is missing field(s): " + ", ".join(missing)
    unexpected = sorted(set(row) - _IPO_SUMMARY_FIELDS)
    if unexpected:
        return "A-share IPO-summary row contains unsupported field(s): " + ", ".join(
            unexpected
        )

    row_code = _row_code(row, ListingMarket.A)
    if row_code is None:
        return "A-share IPO-summary row has no listing code"
    if row_code != listing.code:
        return (
            f"A-share IPO-summary row entity {row_code!r} does not match "
            f"requested listing {listing.canonical_id!r}"
        )

    for field in _IPO_SUMMARY_DATE_FIELDS:
        value = row[field]
        if value is not None and _parse_date_value(value) is None:
            return f"A-share IPO-summary field {field!r} must be a valid date or null"

    for field in _IPO_SUMMARY_NUMERIC_FIELDS:
        value = row[field]
        if value is None:
            continue
        if isinstance(value, bool) or not isinstance(value, Real):
            return f"A-share IPO-summary field {field!r} must be numeric or null"
        try:
            numeric = float(value)
        except (OverflowError, TypeError, ValueError):
            return f"A-share IPO-summary field {field!r} must be numeric or null"
        if not math.isfinite(numeric):
            return f"A-share IPO-summary field {field!r} must be finite or null"

    for field in _IPO_SUMMARY_TEXT_FIELDS:
        value = row[field]
        if value is not None and not isinstance(value, str):
            return f"A-share IPO-summary field {field!r} must be a string or null"
    return None


def _validate_ipo_summary_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> None:
    """Validate the symbol-scoped CNINFO IPO-summary response before storage."""

    message = _ipo_summary_validation_message(rows, listing)
    if message is not None:
        raise ProviderResponseError(message, provider=provider, request=request)


def _ipo_yield_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef | None = None,
) -> tuple[str | None, list[date]]:
    """Return a strict-schema error and listing dates for IPO-yield rows."""

    seen_codes: set[str] = set()
    previous_sequence: int | None = None
    listed_dates: list[date] = []
    for index, row in enumerate(rows):
        missing = sorted(_IPO_YIELD_FIELD_SET - set(row))
        if missing:
            return (
                f"A-share IPO-yield row {index} is missing field(s): "
                + ", ".join(missing),
                [],
            )
        unexpected = sorted(set(row) - _IPO_YIELD_FIELD_SET)
        if unexpected:
            return (
                f"A-share IPO-yield row {index} contains unsupported field(s): "
                + ", ".join(unexpected),
                [],
            )
        if tuple(row) != _IPO_YIELD_FIELDS:
            return (
                f"A-share IPO-yield row {index} must preserve official field order",
                [],
            )

        raw_code = row["股票代码"]
        if not isinstance(raw_code, str) or re.fullmatch(r"\d{6}", raw_code.strip()) is None:
            return (
                f"A-share IPO-yield row {index} 股票代码 must be a six-digit string",
                [],
            )
        row_code = _row_code(row, ListingMarket.A)
        if row_code is None:
            return f"A-share IPO-yield row {index} has no listing code", []
        if listing is not None and row_code != listing.code:
            return (
                f"A-share IPO-yield row entity {row_code!r} does not match "
                f"requested listing {listing.canonical_id!r}",
                [],
            )
        if row_code in seen_codes:
            return (
                f"A-share IPO-yield response has duplicate listing code {row_code!r}",
                [],
            )
        seen_codes.add(row_code)

        name = row["股票简称"]
        if not isinstance(name, str) or not name.strip():
            return (
                f"A-share IPO-yield field '股票简称' in row {index} must be a "
                "non-empty string",
                [],
            )

        sequence_value = row["序号"]
        if isinstance(sequence_value, bool) or not isinstance(sequence_value, Real):
            return (
                f"A-share IPO-yield field '序号' in row {index} must be a "
                "positive integer",
                [],
            )
        try:
            sequence_numeric = float(sequence_value)
        except (OverflowError, TypeError, ValueError):
            return (
                f"A-share IPO-yield field '序号' in row {index} must be a "
                "positive integer",
                [],
            )
        if (
            not math.isfinite(sequence_numeric)
            or not sequence_numeric.is_integer()
            or sequence_numeric < 1
        ):
            return (
                f"A-share IPO-yield field '序号' in row {index} must be a "
                "positive integer",
                [],
            )
        sequence = int(sequence_numeric)
        if previous_sequence is not None and sequence <= previous_sequence:
            return (
                "A-share IPO-yield response 序号 values must be strictly ascending",
                [],
            )
        previous_sequence = sequence

        for field in _IPO_YIELD_DATE_FIELDS:
            value = row[field]
            if value is None:
                continue
            if not isinstance(value, str):
                return (
                    f"A-share IPO-yield field {field!r} must be a valid date or null",
                    [],
                )
            parsed = _parse_date_value(value)
            if parsed is None:
                return (
                    f"A-share IPO-yield field {field!r} must be a valid date or null",
                    [],
                )
            listed_dates.append(parsed)

        for field in _IPO_YIELD_NUMERIC_FIELDS:
            value = row[field]
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"A-share IPO-yield field {field!r} must be numeric or null",
                    [],
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"A-share IPO-yield field {field!r} must be numeric or null",
                    [],
                )
            if not math.isfinite(numeric):
                return (
                    f"A-share IPO-yield field {field!r} must be finite or null",
                    [],
                )

    return None, listed_dates


def _validate_ipo_yield_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> list[date]:
    """Validate the complete Eastmoney IPO-yield universe before filtering."""

    message, listed_dates = _ipo_yield_validation_message(rows)
    if message is not None:
        raise ProviderResponseError(
            f"AKShare {message}",
            provider=provider,
            request=request,
        )
    return listed_dates


def _bid_ask_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
) -> str | None:
    """Return a strict-schema error for one documented bid-ask snapshot."""

    if len(rows) != len(_BID_ASK_ITEM_NAMES):
        return (
            "bid-ask response must contain exactly "
            f"{len(_BID_ASK_ITEM_NAMES)} item/value rows; got {len(rows)}"
        )

    seen: set[str] = set()
    for index, row in enumerate(rows):
        unexpected = sorted(set(row) - {"item", "value"})
        if unexpected:
            return (
                f"bid-ask row {index} contains unsupported field(s): "
                + ", ".join(unexpected)
            )
        if "item" not in row:
            return f"bid-ask row {index} has no item"
        item = row["item"]
        if not isinstance(item, str) or not item.strip():
            return f"bid-ask row {index} item must be a non-empty string"
        if item not in _BID_ASK_ITEM_NAME_SET:
            return f"bid-ask row {index} item {item!r} is not documented"
        if item in seen:
            return f"bid-ask response has duplicate item {item!r}"
        seen.add(item)
        if "value" not in row:
            return f"bid-ask row {index} has no value"
        value = row["value"]
        if value is None:
            continue
        if isinstance(value, bool) or not isinstance(value, Real):
            return f"bid-ask row {index} value must be numeric or null"
        try:
            numeric = float(value)
        except (OverflowError, TypeError, ValueError):
            return f"bid-ask row {index} value must be numeric or null"
        if not math.isfinite(numeric):
            return f"bid-ask row {index} value must be finite or null"

    missing = sorted(_BID_ASK_ITEM_NAME_SET - seen)
    if missing:
        return "bid-ask response is missing item(s): " + ", ".join(missing)
    return None


def _validate_bid_ask_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> None:
    message = _bid_ask_validation_message(rows)
    if message is not None:
        raise ProviderResponseError(
            f"AKShare {message}",
            provider=provider,
            request=request,
        )


def _market_quote_xq_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef | None = None,
) -> tuple[str | None, datetime | None]:
    """Return a strict-schema error and observation time for one Xueqiu quote."""

    expected_fields = {"item", "value"}
    seen_items: set[str] = set()
    observation_time: datetime | None = None
    for index, row in enumerate(rows):
        missing = sorted(expected_fields - set(row))
        unexpected = sorted(set(row) - expected_fields)
        if missing:
            return (
                f"Xueqiu individual-spot row {index} is missing field(s): "
                + ", ".join(missing),
                None,
            )
        if unexpected:
            return (
                f"Xueqiu individual-spot row {index} contains unsupported field(s): "
                + ", ".join(unexpected),
                None,
            )

        item = row["item"]
        if not isinstance(item, str) or not item.strip():
            return (
                f"Xueqiu individual-spot row {index} item must be a non-empty string",
                None,
            )
        if item != item.strip():
            return (
                f"Xueqiu individual-spot row {index} item must match the documented name exactly",
                None,
            )
        if item not in _MARKET_QUOTE_XQ_ITEMS:
            return (
                f"Xueqiu individual-spot row {index} item {item!r} is not documented",
                None,
            )
        if item in seen_items:
            return (
                f"Xueqiu individual-spot response has duplicate item {item!r}",
                None,
            )
        seen_items.add(item)

        value = row["value"]
        if item in _MARKET_QUOTE_XQ_TEXT_ITEMS:
            if value is not None and (not isinstance(value, str) or not value.strip()):
                return (
                    f"Xueqiu individual-spot item {item!r} must be a non-empty string or null",
                    None,
                )
            if item in {"代码", "名称", "时间"} and (
                not isinstance(value, str) or not value.strip()
            ):
                return (
                    f"Xueqiu individual-spot item {item!r} must be a non-empty string",
                    None,
                )
            if item == "时间" and value is not None:
                observation_time = _intraday_history_timestamp(value)
                if observation_time is None:
                    return (
                        "Xueqiu individual-spot item '时间' must be a valid "
                        "YYYY-MM-DD HH:MM:SS timestamp",
                        None,
                    )
            if item == "代码" and value is not None:
                if listing is not None and value.upper() != listing.canonical_id:
                    return (
                        "Xueqiu individual-spot item '代码' "
                        f"{value!r} does not match requested listing "
                        f"{listing.canonical_id!r}",
                        None,
                    )
        elif value is not None:
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"Xueqiu individual-spot item {item!r} must be numeric or null",
                    None,
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"Xueqiu individual-spot item {item!r} must be numeric or null",
                    None,
                )
            if not math.isfinite(numeric):
                return (
                    f"Xueqiu individual-spot item {item!r} must be finite or null",
                    None,
                )

    missing_items = sorted(_MARKET_QUOTE_XQ_REQUIRED_ITEMS - seen_items)
    if missing_items:
        return (
            "Xueqiu individual-spot response is missing item(s): "
            + ", ".join(missing_items),
            None,
        )
    if observation_time is None:
        return (
            "Xueqiu individual-spot response is missing a valid 时间 observation",
            None,
        )
    return None, observation_time


