def _company_metadata_xq_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
) -> str | None:
    """Return a strict-schema error for one Xueqiu company profile."""

    if not rows:
        return "Xueqiu individual-basic-info response is empty"

    expected_fields = {"item", "value"}
    seen_items: set[str] = set()
    for index, row in enumerate(rows):
        missing = sorted(expected_fields - set(row))
        unexpected = sorted(set(row) - expected_fields)
        if missing:
            return (
                f"Xueqiu individual-basic-info row {index} is missing field(s): "
                + ", ".join(missing)
            )
        if unexpected:
            return (
                f"Xueqiu individual-basic-info row {index} contains unsupported field(s): "
                + ", ".join(unexpected)
            )

        item = row["item"]
        if not isinstance(item, str) or not item.strip():
            return (
                f"Xueqiu individual-basic-info row {index} item must be a non-empty string"
            )
        if item != item.strip():
            return (
                f"Xueqiu individual-basic-info row {index} item must match the "
                "documented name exactly"
            )
        if item not in _COMPANY_METADATA_XQ_ITEMS:
            return (
                f"Xueqiu individual-basic-info row {index} item {item!r} "
                "is not documented"
            )
        if item in seen_items:
            return f"Xueqiu individual-basic-info response has duplicate item {item!r}"
        seen_items.add(item)

        value = row["value"]
        if item in _COMPANY_METADATA_XQ_NUMERIC_ITEMS:
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"Xueqiu individual-basic-info item {item!r} must be numeric or null"
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"Xueqiu individual-basic-info item {item!r} must be numeric or null"
                )
            if not math.isfinite(numeric):
                return (
                    f"Xueqiu individual-basic-info item {item!r} must be finite or null"
                )
        elif item in _COMPANY_METADATA_XQ_OBJECT_ITEMS:
            if value is not None and not isinstance(value, Mapping):
                return (
                    f"Xueqiu individual-basic-info item {item!r} must be an object or null"
                )
        elif value is not None and (
            isinstance(value, bool) or not isinstance(value, (str, int, float))
        ):
            return (
                f"Xueqiu individual-basic-info item {item!r} must be a scalar or null"
            )

        if item in _COMPANY_METADATA_XQ_REQUIRED_ITEMS and (
            not isinstance(value, str) or not value.strip()
        ):
            return (
                f"Xueqiu individual-basic-info item {item!r} must be a non-empty string"
            )

    missing_items = sorted(_COMPANY_METADATA_XQ_REQUIRED_ITEMS - seen_items)
    if missing_items:
        return (
            "Xueqiu individual-basic-info response is missing item(s): "
            + ", ".join(missing_items)
        )
    return None


def _validate_company_metadata_xq_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> None:
    """Validate the symbol-scoped Xueqiu company profile before storage."""

    if listing.market is not ListingMarket.A:
        raise ProviderResponseError(
            "AKShare Xueqiu individual-basic-info supports A-share listings only",
            provider=provider,
            request=request,
        )
    message = _company_metadata_xq_validation_message(rows)
    if message is not None:
        raise ProviderResponseError(
            f"AKShare {message}",
            provider=provider,
            request=request,
        )


def _company_metadata_cninfo_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef | None = None,
) -> str | None:
    """Return a strict-schema error for one CNINFO company profile."""

    if len(rows) != 1:
        return (
            "CNINFO company-profile response must contain exactly one row; "
            f"got {len(rows)}"
        )

    row = rows[0]
    missing = sorted(_COMPANY_METADATA_CNINFO_PROFILE_FIELDS - set(row))
    if missing:
        return "CNINFO company-profile row is missing field(s): " + ", ".join(missing)
    unexpected = sorted(set(row) - _COMPANY_METADATA_CNINFO_PROFILE_FIELDS)
    if unexpected:
        return (
            "CNINFO company-profile row contains unsupported field(s): "
            + ", ".join(unexpected)
        )

    for field, value in row.items():
        if value is None:
            continue
        if isinstance(value, bool) or not isinstance(value, (str, Real)):
            return (
                f"CNINFO company-profile field {field!r} must be a scalar or null"
            )
        if isinstance(value, Real):
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"CNINFO company-profile field {field!r} must be a scalar or null"
                )
            if not math.isfinite(numeric):
                return (
                    f"CNINFO company-profile field {field!r} must be finite or null"
                )

    for field in _COMPANY_METADATA_CNINFO_PROFILE_REQUIRED_FIELDS - {"A股代码"}:
        value = row[field]
        if not isinstance(value, str) or not value.strip():
            return (
                f"CNINFO company-profile field {field!r} must be a non-empty string"
            )

    row_code = _canonical_row_code(row["A股代码"], ListingMarket.A)
    if row_code is None:
        return "CNINFO company-profile row has no valid A股代码"
    if listing is not None and row_code != listing.code:
        return (
            f"CNINFO company-profile row entity {row_code!r} does not match "
            f"requested listing {listing.canonical_id!r}"
        )

    for field in _COMPANY_METADATA_CNINFO_PROFILE_DATE_FIELDS:
        value = row[field]
        if _text_value(value) in _MISSING_TEXT:
            continue
        if _parse_date_value(value) is None:
            return (
                f"CNINFO company-profile field {field!r} must be a valid date or null"
            )
    return None


