def _tencent_daily_history_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    *,
    start_date: date,
    end_date: date,
) -> tuple[str | None, list[date]]:
    numeric_fields = _MARKET_HISTORY_TENCENT_DAILY_FIELDS - {"date"}
    observation_dates: list[date] = []
