def _market_activity_hot_rank_latest_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef | None = None,
    *,
    endpoint_name: str = "stock_hot_rank_latest_em",
) -> tuple[str | None, datetime | None]:
    """Return a strict-schema error and ``calcTime`` for one latest-rank slice."""

    if endpoint_name not in _MARKET_ACTIVITY_HOT_RANK_LATEST_ENDPOINTS:
        return (
            "market-activity latest-hot-rank response uses an unsupported endpoint",
            None,
        )
    expected_market = (
        ListingMarket.H
        if endpoint_name == "stock_hk_hot_rank_latest_em"
        else ListingMarket.A
    )
    expected_market_type = _MARKET_ACTIVITY_HOT_RANK_LATEST_MARKET_TYPES[endpoint_name]
    if listing is not None and listing.market is not expected_market:
        return (
            "market-activity latest-hot-rank endpoint supports "
            f"{expected_market.value}-share listings only",
            None,
        )

    expected_fields = {"item", "value"}
    if len(rows) != len(_MARKET_ACTIVITY_HOT_RANK_LATEST_ITEMS):
        return (
            "market-activity latest-hot-rank response must contain exactly "
            f"{len(_MARKET_ACTIVITY_HOT_RANK_LATEST_ITEMS)} item/value rows; got {len(rows)}",
            None,
        )

    seen_items: set[str] = set()
    observation_time: datetime | None = None
    for index, row in enumerate(rows):
        missing = sorted(expected_fields - set(row))
        unexpected = sorted(set(row) - expected_fields)
        if missing:
            return (
                f"market-activity latest-hot-rank row {index} is missing field(s): "
                + ", ".join(missing),
                None,
            )
        if unexpected:
            return (
                f"market-activity latest-hot-rank row {index} contains unsupported "
                "field(s): "
                + ", ".join(unexpected),
                None,
            )

        item = row["item"]
        if not isinstance(item, str) or not item:
            return (
                f"market-activity latest-hot-rank row {index} field 'item' must be "
                "a non-empty string",
                None,
            )
        if item not in _MARKET_ACTIVITY_HOT_RANK_LATEST_ITEMS:
            return (
                f"market-activity latest-hot-rank row {index} contains unsupported "
                f"item {item!r}",
                None,
            )
        if item in seen_items:
            return (
                "market-activity latest-hot-rank response has duplicate item "
                f"{item!r}",
                None,
            )
        seen_items.add(item)

        value = row["value"]
        if item in _MARKET_ACTIVITY_HOT_RANK_LATEST_TEXT_ITEMS:
            if not isinstance(value, str) or not value:
                return (
                    f"market-activity latest-hot-rank item {item!r} must be a "
                    "non-empty string",
                    None,
                )
            if item == "marketType":
                if value != expected_market_type:
                    return (
                        "market-activity latest-hot-rank item 'marketType' must be "
                        f"{expected_market_type!r} for the "
                        f"{expected_market.value}-share endpoint",
                        None,
                    )
            elif item == "calcTime":
                observation_time = _intraday_history_timestamp(value)
                if observation_time is None:
                    return (
                        "market-activity latest-hot-rank item 'calcTime' must be "
                        "a valid YYYY-MM-DD HH:MM:SS timestamp",
                        None,
                    )
            elif item == "innerCode":
                if endpoint_name == "stock_hk_hot_rank_latest_em":
                    if not re.fullmatch(r"\d{5}(?:_\d+)?", value):
                        return (
                            "market-activity latest-hot-rank item 'innerCode' must be "
                            "a five-digit H-share security code",
                            None,
                        )
                    if listing is not None and value[:5] != listing.code:
                        return (
                            "market-activity latest-hot-rank item 'innerCode' "
                            f"{value!r} does not match requested listing "
                            f"{listing.code!r}",
                            None,
                        )
                elif not re.fullmatch(r"\d{6}", value):
                    return (
                        "market-activity latest-hot-rank item 'innerCode' must be a "
                        "six-digit security code",
                        None,
                    )
            elif item == "srcSecurityCode":
                normalized_code = value.upper()
                if endpoint_name == "stock_hk_hot_rank_latest_em":
                    valid_security_code = re.fullmatch(r"HK\|\d{5}", normalized_code)
                    expected_security_code = (
                        None if listing is None else f"HK|{listing.code}"
                    )
                    invalid_message = (
                        "must be an HK| five-digit H-share code"
                    )
                else:
                    valid_security_code = re.fullmatch(
                        r"(?:SH|SZ|BJ)\d{6}", normalized_code
                    )
                    expected_security_code = (
                        None if listing is None else listing.canonical_id
                    )
                    invalid_message = "must be a market-prefixed A-share code"
                if valid_security_code is None:
                    return (
                        "market-activity latest-hot-rank item 'srcSecurityCode' "
                        + invalid_message,
                        None,
                    )
                if (
                    listing is not None
                    and normalized_code != expected_security_code
                ):
                    return (
                        "market-activity latest-hot-rank item 'srcSecurityCode' "
                        f"{value!r} does not match requested listing "
                        f"{listing.canonical_id!r}",
                        None,
                    )
        elif item in _MARKET_ACTIVITY_HOT_RANK_LATEST_INTEGER_ITEMS:
            if value is None:
                if item in {"marketAllCount", "rank"}:
                    return (
                        f"market-activity latest-hot-rank item {item!r} must be a "
                        "positive integer",
                        None,
                    )
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"market-activity latest-hot-rank item {item!r} must be an "
                    "integer or null",
                    None,
                )
            try:
                numeric_value = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"market-activity latest-hot-rank item {item!r} must be an "
                    "integer or null",
                    None,
                )
            if not math.isfinite(numeric_value) or not numeric_value.is_integer():
                return (
                    f"market-activity latest-hot-rank item {item!r} must be an "
                    "integer or null",
                    None,
                )
            if item in {"marketAllCount", "rank"} and numeric_value < 1:
                return (
                    f"market-activity latest-hot-rank item {item!r} must be a "
                    "positive integer",
                    None,
                )

    missing_items = sorted(_MARKET_ACTIVITY_HOT_RANK_LATEST_ITEMS - seen_items)
    if missing_items:
        return (
            "market-activity latest-hot-rank response is missing item(s): "
            + ", ".join(missing_items),
            None,
        )
    if observation_time is None:
        return (
            "market-activity latest-hot-rank response is missing a valid calcTime",
            None,
        )
    return None, observation_time


def _validate_market_activity_hot_rank_latest_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    endpoint_name: str = "stock_hot_rank_latest_em",
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> datetime:
    """Validate an A/H symbol-scoped latest popularity-rank response."""

    message, observation_time = _market_activity_hot_rank_latest_validation_message(
        rows,
        listing,
        endpoint_name=endpoint_name,
    )
    if message is not None:
        raise ProviderResponseError(
            f"AKShare {message}",
            provider=provider,
            request=request,
        )
    assert observation_time is not None
    return observation_time


def _select_esg_rating_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> list[dict[str, JSONValue]]:
    """Filter all agency/quarter rows for one requested A/H listing."""

    selected: list[dict[str, JSONValue]] = []
    for row in rows:
        try:
            row_listing = _esg_rating_row_listing(row)
        except ValueError as exc:
            raise ProviderResponseError(
                f"AKShare returned an invalid ESG-rating row for {request.entity_id!r}: {exc}",
                provider=provider,
                request=request,
            ) from exc
        if row_listing is not None and (
            row_listing.market is listing.market and row_listing.code == listing.code
        ):
            selected.append(dict(row))
    return selected


def _validate_margin_trading_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    observation_date: date,
    require_row_date: bool,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> None:
    """Validate margin security identity and the requested observation date."""

    for row in rows:
        if _margin_trading_row_code(row) is None:
            raise ProviderResponseError(
                f"AKShare returned a margin-trading row without a listing code for "
                f"requested {listing.canonical_id!r}",
                provider=provider,
                request=request,
            )
        has_date, row_date = _margin_trading_date_details(row)
        if require_row_date and not has_date:
            raise ProviderResponseError(
                f"AKShare returned a margin-trading row without an observation date for "
                f"{request.entity_id!r}",
                provider=provider,
                request=request,
            )
        if has_date and row_date is None:
            raise ProviderResponseError(
                f"AKShare returned an invalid margin-trading observation date for "
                f"{request.entity_id!r}",
                provider=provider,
                request=request,
            )
        if has_date and row_date != observation_date:
            raise ProviderResponseError(
                f"AKShare returned margin-trading row date {row_date.isoformat()!r}; "
                f"requested {observation_date.isoformat()!r}",
                provider=provider,
                request=request,
            )


def _select_margin_trading_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
) -> list[dict[str, JSONValue]]:
    """Filter an SSE, SZSE or BSE security universe to the requested listing."""

    selected: list[dict[str, JSONValue]] = []
    for row in rows:
        if _margin_trading_row_code(row) == listing.code:
            selected.append(dict(row))
    return selected


def _validate_trading_suspension_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> None:
    """Validate listing identity and nullable event dates in a suspension universe."""

    for row in rows:
        if _row_code(row, ListingMarket.A) is None:
            raise ProviderResponseError(
                f"AKShare returned a trading-suspension row without a listing code for "
                f"{listing.canonical_id!r}",
                provider=provider,
                request=request,
            )
        for field in _TRADING_SUSPENSIONS_DATE_FIELDS:
            found, raw_date = _lookup(row, (field,))
            if found and _text_value(raw_date) is not None:
                if _parse_date_value(raw_date) is None:
                    raise ProviderResponseError(
                        f"AKShare returned an invalid trading-suspension date in "
                        f"{field!r} for {request.entity_id!r}",
                        provider=provider,
                        request=request,
                    )


def _goodwill_impairment_detail_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
) -> str | None:
    """Return strict-schema errors for goodwill-detail rows."""

    previous_sequence: int | None = None
    for index, row in enumerate(rows):
        missing = sorted(_GOODWILL_IMPAIRMENT_DETAIL_FIELDS - set(row))
        unexpected = sorted(set(row) - _GOODWILL_IMPAIRMENT_DETAIL_FIELDS)
        if missing:
            return (
                f"goodwill-detail row {index} is missing field(s): "
                + ", ".join(missing)
            )
        if unexpected:
            return (
                f"goodwill-detail row {index} contains unsupported field(s): "
                + ", ".join(unexpected)
            )

        sequence = row["序号"]
        if (
            isinstance(sequence, bool)
            or not isinstance(sequence, Integral)
            or sequence <= 0
        ):
            return f"goodwill-detail row {index} field '序号' must be a positive integer"
        if previous_sequence is not None and sequence <= previous_sequence:
            if sequence == previous_sequence:
                return f"goodwill-detail response has duplicate 序号 {sequence!r}"
            return "goodwill-detail response 序号 values must be strictly ascending"
        previous_sequence = sequence

        if _row_code(row, ListingMarket.A) is None:
            return f"goodwill-detail row {index} has no explicit listing code"

        for field in _GOODWILL_IMPAIRMENT_DETAIL_DATE_FIELDS:
            value = row[field]
            if value is not None and _parse_date_value(value) is None:
                return f"goodwill-detail row {index} has an invalid {field}"

        for field in _GOODWILL_IMPAIRMENT_DETAIL_NUMERIC_FIELDS:
            value = row[field]
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"goodwill-detail row {index} field {field!r} "
                    "must be numeric or null"
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"goodwill-detail row {index} field {field!r} "
                    "must be numeric or null"
                )
            if not math.isfinite(numeric):
                return (
                    f"goodwill-detail row {index} field {field!r} "
                    "must be finite or null"
                )

        for field in _GOODWILL_IMPAIRMENT_DETAIL_TEXT_FIELDS:
            value = row[field]
            if value is not None and not isinstance(value, str):
                return (
                    f"goodwill-detail row {index} field {field!r} "
                    "must be a string or null"
                )
    return None


