def _goodwill_impairment_forecast_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
) -> str | None:
    """Return strict-schema errors for goodwill-impairment forecast rows."""

    previous_sequence: int | None = None
    for index, row in enumerate(rows):
        missing = sorted(_GOODWILL_IMPAIRMENT_FORECAST_FIELDS - set(row))
        unexpected = sorted(set(row) - _GOODWILL_IMPAIRMENT_FORECAST_FIELDS)
        if missing:
            return (
                "goodwill-impairment forecast row "
                f"{index} is missing field(s): "
                + ", ".join(missing)
            )
        if unexpected:
            return (
                "goodwill-impairment forecast row "
                f"{index} contains unsupported field(s): "
                + ", ".join(unexpected)
            )

        sequence = row["序号"]
        if (
            isinstance(sequence, bool)
            or not isinstance(sequence, Integral)
            or sequence <= 0
        ):
            return (
                f"goodwill-impairment forecast row {index} field '序号' "
                "must be a positive integer"
            )
        if previous_sequence is not None and sequence <= previous_sequence:
            if sequence == previous_sequence:
                return (
                    "goodwill-impairment forecast response has duplicate 序号 "
                    f"{sequence!r}"
                )
            return (
                "goodwill-impairment forecast response 序号 values must be "
                "strictly ascending"
            )
        previous_sequence = sequence

        if _row_code(row, ListingMarket.A) is None:
            return (
                f"goodwill-impairment forecast row {index} has no explicit listing code"
            )

        for field in _GOODWILL_IMPAIRMENT_FORECAST_DATE_FIELDS:
            value = row[field]
            if value is not None and _parse_date_value(value) is None:
                return (
                    f"goodwill-impairment forecast row {index} has an invalid {field}"
                )

        for field in _GOODWILL_IMPAIRMENT_FORECAST_NUMERIC_FIELDS:
            value = row[field]
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    "goodwill-impairment forecast row "
                    f"{index} field {field!r} must be numeric or null"
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    "goodwill-impairment forecast row "
                    f"{index} field {field!r} must be numeric or null"
                )
            if not math.isfinite(numeric):
                return (
                    "goodwill-impairment forecast row "
                    f"{index} field {field!r} must be finite or null"
                )

        for field in _GOODWILL_IMPAIRMENT_FORECAST_TEXT_FIELDS:
            value = row[field]
            if value is not None and not isinstance(value, str):
                return (
                    "goodwill-impairment forecast row "
                    f"{index} field {field!r} must be a string or null"
                )
    return None


def _goodwill_impairment_market_profile_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
) -> tuple[str | None, list[date]]:
    """Return strict-schema errors for the market-wide goodwill history."""

    report_periods: list[date] = []
    previous_period: date | None = None
    for index, row in enumerate(rows):
        missing = sorted(_GOODWILL_IMPAIRMENT_MARKET_PROFILE_FIELDS - set(row))
        unexpected = sorted(set(row) - _GOODWILL_IMPAIRMENT_MARKET_PROFILE_FIELDS)
        if missing:
            return (
                "goodwill-impairment market-profile row "
                f"{index} is missing field(s): "
                + ", ".join(missing),
                [],
            )
        if unexpected:
            return (
                "goodwill-impairment market-profile row "
                f"{index} contains unsupported field(s): "
                + ", ".join(unexpected),
                [],
            )

        report_period = _parse_date_value(row["报告期"])
        if report_period is None:
            return (
                f"goodwill-impairment market-profile row {index} has an invalid 报告期",
                [],
            )
        if previous_period is not None and report_period <= previous_period:
            if report_period == previous_period:
                return (
                    "goodwill-impairment market-profile response has duplicate 报告期 "
                    f"{report_period.isoformat()!r}",
                    [],
                )
            return (
                "goodwill-impairment market-profile response 报告期 values must be "
                "strictly ascending",
                [],
            )
        previous_period = report_period
        report_periods.append(report_period)

        for field in _GOODWILL_IMPAIRMENT_MARKET_PROFILE_NUMERIC_FIELDS:
            value = row[field]
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    "goodwill-impairment market-profile row "
                    f"{index} field {field!r} must be numeric or null",
                    [],
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    "goodwill-impairment market-profile row "
                    f"{index} field {field!r} must be numeric or null",
                    [],
                )
            if not math.isfinite(numeric):
                return (
                    "goodwill-impairment market-profile row "
                    f"{index} field {field!r} must be finite or null",
                    [],
                )
    return None, report_periods


