def _validate_ownership_pledge_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    observation_date: date,
) -> None:
    """Keep replayed pledge snapshots bound to the requested A-share listing."""

    for row in rows:
        row_code = _row_code(row, listing.market)
        if row_code is None:
            raise ProviderNormalizationError(
                "ownership-pledge row has no explicit listing code"
            )
        if row_code != listing.code:
            raise ProviderNormalizationError(
                f"ownership-pledge row entity {row_code!r} does not match "
                f"requested listing {listing.canonical_id!r}"
            )
        row_date = _observation_date(row)
        if row_date is None:
            raise ProviderNormalizationError(
                "ownership-pledge row has no exact observation date"
            )
        if row_date != observation_date:
            raise ProviderNormalizationError(
                f"ownership-pledge row date {row_date.isoformat()!r} does not match "
                f"requested observation date {observation_date.isoformat()!r}"
            )


def _validate_ownership_pledge_detail_normalizer_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
) -> None:
    """Validate replayed symbol-scoped individual pledge-detail rows."""

    for row in rows:
        row_code = _row_code(row, ListingMarket.A)
        if row_code is None:
            raise ProviderNormalizationError(
                "individual ownership-pledge row has no explicit listing code"
            )
        if row_code != listing.code:
            raise ProviderNormalizationError(
                f"individual ownership-pledge row entity {row_code!r} does not match "
                f"requested listing {listing.canonical_id!r}"
            )
        for field in _OWNERSHIP_PLEDGE_DETAIL_DATE_FIELDS:
            found, raw_date = _lookup(row, (field,))
            if found and _text_value(raw_date) is not None:
                if _parse_date_value(raw_date) is None:
                    raise ProviderNormalizationError(
                        f"individual ownership-pledge row has an invalid date in {field!r}"
                    )


