def _shareholder_count_detail_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
) -> tuple[str | None, list[date]]:
    """Validate the exact Eastmoney shareholder-count-detail table schema."""

    observation_dates: list[date] = []
    previous_observation_date: date | None = None
    for index, row in enumerate(rows):
        if (
            set(row) != _SHAREHOLDER_COUNT_DETAIL_FIELD_SET
            or tuple(row) != _SHAREHOLDER_COUNT_DETAIL_FIELDS
        ):
            return (
                f"shareholder-count-detail response row {index} fields do not match "
                "the exact schema",
                [],
            )

        raw_code = row["代码"]
        if not isinstance(raw_code, str) or re.fullmatch(r"\d{6}", raw_code) is None:
            return (
                f"shareholder-count-detail row {index} code must be a six-digit string",
                [],
            )
        if raw_code != listing.code:
            return (
                f"shareholder-count-detail row {index} code {raw_code!r} does not "
                f"match requested listing {listing.canonical_id!r}",
                [],
            )

        raw_name = row["名称"]
        if (
            not isinstance(raw_name, str)
            or not raw_name.strip()
            or raw_name.strip().lower() in _MISSING_TEXT
        ):
            return (
                f"shareholder-count-detail row {index} name must be non-empty text",
                [],
            )
        raw_reason = row["股本变动原因"]
        if raw_reason is not None and not isinstance(raw_reason, str):
            return (
                f"shareholder-count-detail row {index} field '股本变动原因' "
                "must be text or null",
                [],
            )

        raw_observation_date = row["股东户数统计截止日"]
        if (
            not isinstance(raw_observation_date, str)
            or not raw_observation_date.strip()
        ):
            return (
                f"shareholder-count-detail row {index} has no observation date",
                [],
            )
        observation_date = _parse_date_value(raw_observation_date)
        if observation_date is None:
            return (
                f"shareholder-count-detail row {index} has an invalid observation date",
                [],
            )
        if (
            previous_observation_date is not None
            and observation_date < previous_observation_date
        ):
            return (
                "shareholder-count-detail observation dates must be non-decreasing",
                [],
            )
        previous_observation_date = observation_date
        observation_dates.append(observation_date)

        raw_announcement_date = row["股东户数公告日期"]
        if raw_announcement_date is not None:
            if (
                not isinstance(raw_announcement_date, str)
                or _parse_date_value(raw_announcement_date) is None
            ):
                return (
                    f"shareholder-count-detail row {index} has an invalid announcement "
                    "date",
                    [],
                )

        for field in _SHAREHOLDER_COUNT_DETAIL_NUMERIC_FIELDS:
            value = row[field]
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"shareholder-count-detail row {index} field {field!r} must be "
                    "numeric or null",
                    [],
                )
            if field in _SHAREHOLDER_COUNT_DETAIL_INTEGER_FIELDS and not isinstance(
                value, Integral
            ):
                return (
                    f"shareholder-count-detail row {index} field {field!r} must be "
                    "an integer or null",
                    [],
                )
            numeric = float(value)
            if not math.isfinite(numeric):
                return (
                    f"shareholder-count-detail row {index} field {field!r} must be "
                    "finite or null",
                    [],
                )
            if (
                field in _SHAREHOLDER_COUNT_DETAIL_NON_NEGATIVE_FIELDS
                and numeric < 0
            ):
                return (
                    f"shareholder-count-detail row {index} field {field!r} must be "
                    "non-negative or null",
                    [],
                )

    return None, observation_dates


def _validate_shareholder_count_detail_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> tuple[date | None, date | None]:
    """Validate the listing-scoped Eastmoney detail response before storage."""

    message, observation_dates = _shareholder_count_detail_validation_message(
        rows,
        listing,
    )
    if message is not None:
        raise ProviderResponseError(
            f"AKShare {message} for {request.entity_id!r}",
            provider=provider,
            request=request,
        )
    if not observation_dates:
        return None, None
    return observation_dates[0], observation_dates[-1]


def _validate_shareholder_count_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    observation_date: date,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> None:
    """Validate the full CNINFO shareholder-count universe before filtering."""

    for row in rows:
        if _row_code(row, ListingMarket.A) is None:
            raise ProviderResponseError(
                f"AKShare returned a shareholder-count row without a listing code for "
                f"{request.entity_id!r}",
                provider=provider,
                request=request,
            )
        found, raw_date = _lookup(row, _SHAREHOLDER_COUNT_DATE_FIELDS)
        if not found or _text_value(raw_date) in _MISSING_TEXT:
            raise ProviderResponseError(
                f"AKShare returned a shareholder-count row without an observation date "
                f"for {request.entity_id!r}",
                provider=provider,
                request=request,
            )
        row_date = _parse_date_value(raw_date)
        if row_date is None:
            raise ProviderResponseError(
                f"AKShare returned an invalid shareholder-count observation date for "
                f"{request.entity_id!r}",
                provider=provider,
                request=request,
            )
        if row_date != observation_date:
            raise ProviderResponseError(
                f"AKShare returned shareholder-count row date {row_date.isoformat()!r}; "
                f"requested {observation_date.isoformat()!r}",
                provider=provider,
                request=request,
            )


def _validate_shareholder_holdings_normalizer_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
) -> None:
    """Validate dates in replayed main-shareholder rows."""

    for row in rows:
        for field in _SHAREHOLDER_HOLDINGS_DATE_FIELDS:
            found, raw_date = _lookup(row, (field,))
            if found and _text_value(raw_date) not in _MISSING_TEXT:
                if _parse_date_value(raw_date) is None:
                    raise ProviderNormalizationError(
                        f"main-shareholder row has an invalid date in {field!r}"
                    )


def _validate_shareholder_free_holding_detail_normalizer_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    report_period: date,
) -> None:
    """Keep replayed tradable-holder detail rows inside listing/period scope."""

    for row in rows:
        row_code = _row_code(row, ListingMarket.A)
        if row_code is None:
            raise ProviderNormalizationError(
                "free-holding-detail row has no explicit listing code"
            )
        if row_code != listing.code:
            raise ProviderNormalizationError(
                f"free-holding-detail row entity {row_code!r} does not match "
                f"requested listing {listing.canonical_id!r}"
            )
        found_holder, raw_holder = _lookup(
            row,
            _SHAREHOLDER_FREE_HOLDING_DETAIL_HOLDER_FIELDS,
        )
        if not found_holder or _text_value(raw_holder) is None:
            raise ProviderNormalizationError(
                "free-holding-detail row has no holder name"
            )
        found_period, raw_period = _lookup(
            row,
            _SHAREHOLDER_FREE_HOLDING_DETAIL_PERIOD_FIELDS,
        )
        if not found_period or _text_value(raw_period) is None:
            raise ProviderNormalizationError(
                "free-holding-detail row has no exact report period"
            )
        row_period = _parse_date_value(raw_period)
        if row_period is None:
            raise ProviderNormalizationError(
                "free-holding-detail row has an invalid report period"
            )
        if row_period != report_period:
            raise ProviderNormalizationError(
                f"free-holding-detail row period {row_period.isoformat()!r} does not "
                f"match requested report period {report_period.isoformat()!r}"
            )
        found_announcement, raw_announcement = _lookup(
            row,
            _SHAREHOLDER_FREE_HOLDING_DETAIL_ANNOUNCEMENT_FIELDS,
        )
        if (
            found_announcement
            and _text_value(raw_announcement) is not None
            and _parse_date_value(raw_announcement) is None
        ):
            raise ProviderNormalizationError(
                "free-holding-detail row has an invalid announcement date"
            )


def _validate_shareholder_top10_normalizer_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    label: str = "top-ten-shareholder",
) -> None:
    """Keep replayed ranked-holder rows inside their optional listing scope."""

    seen_ranks: set[int] = set()
    for row in rows:
        row_code = _row_code(row, ListingMarket.A)
        if row_code is not None and row_code != listing.code:
            raise ProviderNormalizationError(
                f"{label} row entity {row_code!r} does not match "
                f"requested listing {listing.canonical_id!r}"
            )
        found_rank, raw_rank = _lookup(row, _SHAREHOLDER_TOP10_RANK_FIELDS)
        rank = _top10_rank_value(raw_rank) if found_rank else None
        if rank is None:
            raise ProviderNormalizationError(
                f"{label} row has no valid rank"
            )
        if rank in seen_ranks:
            raise ProviderNormalizationError(
                f"{label} row has duplicate rank {rank!r}"
            )
        found_holder, raw_holder = _lookup(row, _SHAREHOLDER_TOP10_HOLDER_FIELDS)
        if not found_holder or _text_value(raw_holder) is None:
            raise ProviderNormalizationError(
                f"{label} row has no holder name"
            )
        seen_ranks.add(rank)


