def _market_activity_date_parameter(
    raw_value: object,
    *,
    name: str,
    request: ProviderRequest,
) -> date:
    if not isinstance(raw_value, str) or not re.fullmatch(r"\d{8}", raw_value):
        raise ProviderRequestError(
            f"market-activity {name} must be YYYYMMDD",
            request=request,
            retryable=False,
        )
    try:
        return datetime.strptime(raw_value, "%Y%m%d").date()
    except ValueError as exc:
        raise ProviderRequestError(
            f"market-activity {name} must be a valid YYYYMMDD date",
            request=request,
            retryable=False,
        ) from exc


def _market_activity_month_parameter(
    raw_value: object,
    *,
    name: str,
    request: ProviderRequest,
) -> date:
    if not isinstance(raw_value, str) or not re.fullmatch(r"\d{6}", raw_value):
        raise ProviderRequestError(
            f"market-activity {name} must be YYYYMM",
            request=request,
            retryable=False,
        )
    try:
        return datetime.strptime(raw_value, "%Y%m").date()
    except ValueError as exc:
        raise ProviderRequestError(
            f"market-activity {name} must be a valid YYYYMM month",
            request=request,
            retryable=False,
        ) from exc


def _market_activity_date_range(request: ProviderRequest) -> tuple[date, date]:
    if not {"start_date", "end_date"}.issubset(request.parameters):
        raise ProviderRequestError(
            "the AKShare market-activity endpoint requires start_date and end_date "
            "(YYYYMMDD)",
            request=request,
            retryable=False,
        )
    start_date = _market_activity_date_parameter(
        request.parameters["start_date"],
        name="start_date",
        request=request,
    )
    end_date = _market_activity_date_parameter(
        request.parameters["end_date"],
        name="end_date",
        request=request,
    )
    if start_date > end_date:
        raise ProviderRequestError(
            "market-activity start_date must not be after end_date",
            request=request,
            retryable=False,
        )
    return start_date, end_date


def _market_activity_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    """Build one documented market-activity request."""

    if endpoint_name == "stock_market_pe_lg":
        return _market_activity_market_pe_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_index_pe_lg":
        return _market_activity_index_pe_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_market_pb_lg":
        return _market_activity_market_pb_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_a_all_pb":
        return _market_activity_all_pb_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_a_ttm_lyr":
        return _market_activity_ttm_lyr_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_buffett_index_lg":
        return _market_activity_buffett_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_ebs_lg":
        return _market_activity_ebs_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_a_congestion_lg":
        return _market_activity_congestion_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_market_activity_legu":
        return _market_activity_legu_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_account_statistics_em":
        return _market_activity_account_statistics_kwargs(
            endpoint_name,
            listing,
            request,
        )
    if endpoint_name == "stock_zt_pool_em":
        return _market_activity_limit_up_pool_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_zt_pool_dtgc_em":
        return _market_activity_limit_down_pool_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_zh_a_new_em":
        return _market_activity_new_stock_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_comment_detail_scrd_desire_em":
        return _market_activity_participation_desire_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_comment_detail_scrd_focus_em":
        return _market_activity_focus_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_comment_detail_zlkp_jgcyd_em":
        return _market_activity_institution_participation_kwargs(
            endpoint_name,
            listing,
            request,
        )
    if endpoint_name == "stock_hot_rank_em":
        return _market_activity_hot_rank_kwargs(endpoint_name, listing, request)
    if endpoint_name == _MARKET_ACTIVITY_HOT_RANK_DETAIL_ENDPOINT:
        return _market_activity_hot_rank_detail_kwargs(endpoint_name, listing, request)
    if endpoint_name == _MARKET_ACTIVITY_HK_HOT_RANK_DETAIL_ENDPOINT:
        return _market_activity_hk_hot_rank_detail_kwargs(endpoint_name, listing, request)
    if endpoint_name in _MARKET_ACTIVITY_HOT_RANK_LATEST_ENDPOINTS:
        return _market_activity_hot_rank_latest_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_lhb_stock_statistic_em":
        return _market_activity_statistic_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_lhb_jgstatistic_em":
        return _market_activity_institution_statistic_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_lhb_jgmmtj_em":
        return _market_activity_institution_daily_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_jgdy_detail_em":
        return _market_activity_institution_research_detail_kwargs(
            endpoint_name,
            listing,
            request,
        )
    if endpoint_name == "stock_jgdy_tj_em":
        return _market_activity_institution_research_kwargs(
            endpoint_name,
            listing,
            request,
        )
    if endpoint_name == "stock_dzjy_mrmx":
        return _market_activity_block_trade_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_board_industry_name_em":
        return _market_activity_industry_board_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_szse_area_summary":
        return _market_activity_szse_area_summary_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_szse_sector_summary":
        return _market_activity_szse_sector_summary_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_szse_summary":
        return _market_activity_szse_summary_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_sse_summary":
        return _market_activity_sse_summary_kwargs(endpoint_name, listing, request)
    if endpoint_name == "stock_sse_deal_daily":
        return _market_activity_sse_deal_daily_kwargs(endpoint_name, listing, request)

    if endpoint_name != "stock_lhb_detail_em":
        raise ProviderRequestError(
            f"unsupported AKShare market-activity endpoint {endpoint_name!r}",
            request=request,
            retryable=False,
        )
    if listing.market is not ListingMarket.A:
        raise ProviderRequestError(
            "the AKShare market-activity endpoint supports A-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(set(request.parameters) - _MARKET_ACTIVITY_PARAMETER_NAMES)
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare market-activity parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    _market_activity_date_range(request)
    return {
        "start_date": request.parameters["start_date"],
        "end_date": request.parameters["end_date"],
    }


def _market_activity_market_pe_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    """Build the documented market-PE request with an explicit board symbol."""

    if endpoint_name != "stock_market_pe_lg":
        raise ProviderRequestError(
            f"unsupported AKShare market-PE endpoint {endpoint_name!r}",
            request=request,
            retryable=False,
        )
    if listing.market is not ListingMarket.A:
        raise ProviderRequestError(
            "the AKShare market-PE endpoint supports A-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(
        set(request.parameters) - _MARKET_ACTIVITY_MARKET_PE_PARAMETER_NAMES
    )
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare market-PE parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    if request.parameters.get("view") != _MARKET_ACTIVITY_MARKET_PE_VIEW:
        raise ProviderRequestError(
            "AKShare market-PE endpoint requires "
            f"view={_MARKET_ACTIVITY_MARKET_PE_VIEW!r}",
            request=request,
            retryable=False,
        )
    symbol = request.parameters.get("symbol")
    if symbol not in _MARKET_ACTIVITY_MARKET_PE_SYMBOLS:
        raise ProviderRequestError(
            "AKShare market-PE endpoint requires symbol in "
            + repr(_MARKET_ACTIVITY_MARKET_PE_SYMBOLS),
            request=request,
            retryable=False,
        )
    return {"symbol": symbol}


